async (page) => {
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  const check=(ok,msg)=>{if(!ok)throw new Error(msg)};
  const goto=async path=>{await page.goto('http://127.0.0.1:5173/?demo=1#'+path);await page.locator('.design-screen').waitFor();await page.evaluate(()=>document.fonts.ready)};
  const checks=[];
  await page.setViewportSize({width:390,height:844});
  await goto('/');
  await page.getByRole('heading',{name:'鲜虾蟹籽 云吞'}).waitFor();
  await page.screenshot({path:'output/prototype/app-home.png'});
  await page.getByRole('button',{name:'换一个'}).click();
  await page.getByRole('heading',{name:'番茄 牛腩饭'}).waitFor();
  await page.getByRole('link',{name:'就它了'}).click();
  await page.waitForURL('**#/foods/2');
  await page.getByRole('heading',{name:'番茄 牛腩饭'}).waitFor();
  checks.push('首页转盘切换、正确菜品详情');
  await page.screenshot({path:'output/prototype/app-dish.png'});
  const fav=page.getByRole('button',{name:/^(收藏|已收藏|取消收藏)$/});
  const initial=await fav.getAttribute('aria-pressed');await fav.click();
  await page.waitForFunction(value=>document.querySelector('header button')?.getAttribute('aria-pressed')!==value,initial);
  await fav.click();
  const like=page.getByRole('button',{name:'127',exact:true});await like.click();
  await page.getByRole('button',{name:/^(126|128)$/,exact:true}).waitFor();
  await page.getByRole('button',{name:/^(126|128)$/,exact:true}).click();
  await page.getByRole('button',{name:'127',exact:true}).waitFor();
  checks.push('收藏与点赞回显、恢复原状态');
  await page.getByRole('button',{name:'平价 4'}).click();
  await page.locator('.mobile-panel-layer').waitFor();
  await page.getByRole('button',{name:'鲜虾大只',exact:true}).waitFor();
  await page.screenshot({path:'output/prototype/app-tags-panel.png'});
  checks.push('详情标签面板');
  const panel=page.getByRole('dialog',{name:'加标签'});
  await panel.getByRole('button',{name:'＋ 自己写'}).click();
  const tagName='测试标签'+Date.now().toString().slice(-4);
  await page.getByRole('textbox',{name:'写一个我的标签'}).fill(tagName);
  await page.getByRole('button',{name:'加上',exact:true}).click();
  await panel.getByRole('button',{name:tagName,exact:true}).waitFor();
  await panel.getByRole('link',{name:'好了',exact:true}).click();
  await goto('/me/tags');
  await page.getByRole('link').filter({hasText:tagName}).waitFor();
  await page.getByRole('button',{name:'管理',exact:true}).click();
  const row=page.locator('li').filter({hasText:tagName});
  await row.getByRole('button',{name:'改名'}).click();
  await page.getByRole('textbox',{name:'改标签名'}).fill(tagName+'改');
  await page.getByRole('button',{name:'好了',exact:true}).click();
  await page.getByRole('link').filter({hasText:tagName+'改'}).waitFor();
  await page.locator('li').filter({hasText:tagName+'改'}).getByRole('button',{name:'删除',exact:true}).click();
  await page.getByRole('button',{name:'删除分类',exact:true}).click();
  await page.getByRole('link').filter({hasText:tagName+'改'}).waitFor({state:'detached'});
  checks.push('自定义标签创建、改名、二次确认删除');
  await goto('/nearby');await page.getByRole('heading',{name:/附近/}).waitFor();
  await page.getByRole('link').filter({hasText:'袁记云饺'}).last().waitFor();
  await page.screenshot({path:'output/prototype/app-nearby.png'});
  await goto('/publish');
  await page.getByRole('radio',{name:/袁记云饺/}).click();
  await page.getByRole('link',{name:/下一步/}).click();
  await page.getByRole('textbox',{name:'菜名',exact:true}).fill('验收测试菜');
  await page.getByRole('textbox',{name:'价格',exact:true}).fill('0');
  const chooser=page.waitForEvent('filechooser');
  await page.getByRole('button',{name:'再加一张照片'}).click();
  await (await chooser).setFiles('prototype/assets/photos/sq_luosi.png');
  await page.waitForURL('**#/publish/crop');
  await page.getByRole('slider',{name:'缩放'}).fill('1.25');
  await page.getByRole('link',{name:'完成',exact:true}).click();
  await page.waitForURL('**#/publish/dish');
  check(await page.getByRole('textbox',{name:'菜名',exact:true}).inputValue()==='验收测试菜','裁剪后丢失草稿');
  await page.getByRole('radio',{name:'小吃',exact:true}).click();
  await page.getByRole('textbox',{name:/说两句/}).fill('自动验收：本地裁剪照片和零元价格');
  await page.screenshot({path:'output/prototype/app-publish.png'});
  await page.getByRole('link',{name:'发布',exact:true}).click();
  await page.waitForURL('**#/me?tab=uploads');
  await page.getByRole('button',{name:'知道了'}).click();
  await page.getByRole('heading',{name:'验收测试菜',exact:true}).waitFor();
  checks.push('选店、图片裁剪、分类、草稿恢复、零元价格发布');
  await goto('/me/edit');
  const report={checks,errors};await page.evaluate(data=>sessionStorage.setItem('eatwhat-qa-business',JSON.stringify(data)),report);return report;
}
